'use strict';
window.NexoMonitor=(()=>{
const C=NexoCore;const state={mode:'idle',data:null,history:[],token:'',url:'',paused:false,error:'',received:0,busy:false,showIPs:false,map:'topology',selected:null,filter:'',lastAttempt:0,testProxy:false};
try{state.url=localStorage.getItem('nexo-monitor-url')||'';}catch{}
let timer=null,controller=null,revision=0;
const fmt=(n,d=1)=>Number.isFinite(n)?n.toLocaleString('es-EC',{maximumFractionDigits:d}):'—';
function bytes(n){if(!Number.isFinite(n))return '—';let unit=0;const names=['B','KiB','MiB','GiB','TiB'];while(n>=1024&&unit<4){n/=1024;unit++;}return fmt(n)+' '+names[unit];}
function rate(n){if(!Number.isFinite(n))return '—';const u=n>=1e9?1e9:n>=1e6?1e6:n>=1e3?1e3:1;return fmt(n/u)+' '+({1:'bps',1000:'Kbps',1000000:'Mbps',1000000000:'Gbps'})[u];}
function duration(n){if(!Number.isFinite(n))return '—';return n>=86400?fmt(n/86400,1)+' días':n>=3600?fmt(n/3600,1)+' h':fmt(n/60,0)+' min';}
const safeIP=ip=>esc(state.showIPs?ip:C.maskIP(ip));
function currentPage(){return location.hash.slice(1)||'recursos';}
function status(){if(state.mode==='demo')return ['demo','Demostración'];if(state.paused)return ['paused','En pausa'];if(state.mode==='live'&&state.error)return ['offline','Sin respuesta'];if(state.mode==='live'&&state.data&&Date.now()-Date.parse(state.data.timestamp)>20000)return ['offline','Muestra vencida'];if(state.mode==='live'&&state.data)return ['online','En directo'];return ['idle','Sin agente'];}
function spark(points,key,color,max,unit=''){const w=550,h=145,pad=26;const vals=points.map(p=>p[key]);const observed=vals.filter(Number.isFinite);const roof=max||Math.max(...observed,1)*1.15;let segments=[],segment=[];vals.forEach((v,i)=>{if(!Number.isFinite(v)){if(segment.length)segments.push(segment);segment=[];return;}segment.push(`${pad+i/Math.max(vals.length-1,1)*(w-pad-8)},${h-pad-v/roof*(h-pad-12)}`);});if(segment.length)segments.push(segment);return `<svg viewBox="0 0 ${w} ${h}" class="metric-chart" role="img" aria-label="Historial de ${esc(key)}${observed.length?'':' sin muestras'}">${[0,.5,1].map(f=>`<line x1="${pad}" x2="${w-8}" y1="${h-pad-f*(h-pad-12)}" y2="${h-pad-f*(h-pad-12)}" stroke="#26333b" stroke-dasharray="3 5"/><text x="0" y="${h-pad-f*(h-pad-12)+3}" fill="#637e8a" font-size="8">${max?fmt(roof*f,0)+unit:f===0?'0':''}</text>`).join('')}${segments.map(s=>`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${s.join(' ')}"/>`).join('')}${observed.length===1?`<circle cx="${pad}" cy="${h-pad-observed[0]/roof*(h-pad-12)}" r="3" fill="${color}"/>`:''}${!observed.length?`<text x="285" y="70" fill="#718b98" text-anchor="middle" font-size="12">Esperando muestras del agente</text>`:''}<text x="${pad}" y="${h-5}" fill="#637e8a" font-size="9">${points.length?esc(new Date(points[0].time).toLocaleTimeString('es-EC')):'Sin historial'}</text><text x="${w-8}" y="${h-5}" fill="#637e8a" text-anchor="end" font-size="9">${points.length?esc(new Date(points[points.length-1].time).toLocaleTimeString('es-EC')):''}</text></svg>`;}
function tools(){const [st,label]=status();return `<div class="monitor-bar"><div class="monitor-server"><span class="server-icon">▤</span><div><strong>${esc(state.data?.server.name||'Conecta tu servidor Linux')}</strong><p>${state.mode==='demo'?'Datos simulados · no pertenecen a tu infraestructura':state.data?esc(state.data.server.os)+' · '+fmt(state.data.server.cpu_count,0)+' CPU lógicas':'Agente de solo lectura · sin datos recibidos'}</p></div></div><div class="monitor-controls"><span class="live-status ${st}"><i></i>${label}</span>${state.mode!=='idle'?`<button data-monitor="pause" class="small">${state.paused?'▶ Reanudar':'Ⅱ Pausar'}</button>`:''}<button data-monitor="settings" class="small">⚙ Conectar agente</button><button data-monitor="demo" class="small">${state.mode==='demo'?'Salir de demo':'Ver demostración'}</button></div></div>${state.mode==='demo'?'<div class="demo-notice">DEMOSTRACIÓN ACTIVA · CPU, tráfico, conexiones y ubicaciones son simulados. <button data-monitor="settings">Conectar datos reales →</button></div>':''}${state.error?`<div class="monitor-error" role="alert"><strong>Sin actualización.</strong> ${esc(state.error)}${state.data?' Se conserva la última muestra; los valores no representan el estado actual.':''}</div>`:''}`;}
function stamp(){const d=state.data;return `<div class="monitor-stamp"><span>${d?'Muestra: '+esc(new Date(d.timestamp).toLocaleString('es-EC')):'Esperando primera muestra'}${state.paused?' · Actualización detenida':''}</span><span>Consulta cada 5 s · Historial de esta sesión (hasta 10 min)</span></div>`;}
function cards(){const d=state.data,n=d?.network,mem=d?.memory,disk=d?.disks[0];const items=[['CPU',d?.cpu.percent===null||!d?'—':fmt(d.cpu.percent)+'<em>%</em>',d?'Carga 1 min: '+fmt(d.cpu.load_average?.[0]):'Uso total del procesador',d?.cpu.percent,'#b9f385'],['Memoria RAM',mem?fmt(mem.used_percent)+'<em>%</em>':'—',mem?bytes(mem.used_bytes)+' de '+bytes(mem.total_bytes):'Memoria usada sin caché recuperable',mem?.used_percent,'#8ec9fd'],['Disco '+esc(disk?.path||'/'),disk?fmt(disk.used_percent)+'<em>%</em>':'—',disk?bytes(disk.used_bytes)+' de '+bytes(disk.total_bytes):'Espacio del sistema de archivos',disk?.used_percent,'#d3b9ff'],['Tráfico de salida',n?rate(n.tx_bps):'—',n?'↓ Entrada: '+rate(n.rx_bps):'Bitrate agregado de las interfaces',n?.capacity_bps>0&&n.tx_bps!==null?Math.min(100,n.tx_bps/n.capacity_bps*100):null,'#f5c47a']];return `<div class="stats monitor-stats">${items.map(([title,val,sub,p,color])=>`<article class="stat resource-card"><div class="stat-label">${title}<span class="metric-glyph" style="color:${color}">◴</span></div><div class="stat-value">${val}</div><small>${sub}</small><div class="resource-meter"><span style="width:${Number.isFinite(p)?p:0}%;background:${color}"></span></div>${title.startsWith('Tráfico')?`<small>${n?.capacity_bps?'Capacidad configurada: '+rate(n.capacity_bps):'Capacidad del enlace sin configurar'}</small>`:''}</article>`).join('')}</div>`;}
function alarmPanel(){const a=C.alerts(state.data);const bad=['offline','paused'].includes(status()[0]);return `<section class="panel monitor-alerts"><div class="panel-top"><div><h2>Estado y alertas</h2><p>Umbrales locales · CPU 85% · RAM 90% · Espacio 90% · Carga 15 min / CPU > 1</p></div><span class="badge ${a.length||bad?'muted':''}">${state.data?a.length+' alertas de recursos':'Sin datos'}</span></div><div class="alerts-body">${state.data?(a.length?a.map(v=>`<div class="alert-row ${v.level}"><span>△</span><div><strong>${esc(v.title)}</strong><p>${esc(v.detail)}</p></div></div>`).join(''):`<div class="alert-row"><span>✓</span><div><strong>${bad?'Última muestra sin umbrales excedidos':'Sin umbrales excedidos en la muestra'}</strong><p>${bad?'La telemetría no se está actualizando.':'Las alertas se evalúan sobre cada muestra recibida.'}</p></div></div>`):'<div class="alert-row"><span>◌</span><div><strong>Esperando telemetría</strong><p>Sin datos no se puede determinar la salud del servidor.</p></div></div>'}<div class="alert-note">Se evalúan mientras el panel está abierto. No envían notificaciones ni guardan un historial en el servidor.</div></div></section>`;}
function dashboardTiles(){const d=state.data;const demo=state.mode==='demo';const online=d?.connections.established;const lines=d?.sessions?d.sessions.length:null;const tiles=[['purple','bolt','Conexiones online',fmt(online,0),'Sockets TCP en los puertos monitorizados; no equivale a espectadores.','#conexiones'],['green','users','Sesiones IPTV',fmt(lines,0),'Sesiones activas reportadas por la integración IPTV; puede haber varias por cliente.','#conexiones'],['cyan','play','Señales en vivo',demo?'3':'—',demo?'Estado simulado de señales de demostración.':'Requiere integrar la supervisión de fuentes; no se deduce de los canales habilitados.','#canales'],['pink','alert','Señales caídas',demo?'0':'—',demo?'Estado simulado de señales de demostración.':'Requiere integrar la supervisión de fuentes.','#canales'],['blue','up','Salida de red',d?rate(d.network.tx_bps):'—','Tráfico de salida agregado de las interfaces monitorizadas.','#recursos'],['orange','down','Entrada de red',d?rate(d.network.rx_bps):'—','Tráfico de entrada agregado de las interfaces monitorizadas.','#recursos']];return `<div class="dashboard-tiles" aria-label="Resumen de operación">${tiles.map(([color,icon,label,value,help,href])=>`<a class="dashboard-tile ${color}" href="${href}" title="${help}"><span class="tile-square one"></span><span class="tile-square two"></span><span class="tile-square three"></span><span class="tile-icon">${NexoShell.icon(icon)}</span><div class="tile-content"><strong>${value.replace(/ (Mbps|Kbps|Gbps|bps)$/,' <small>$1</small>')}</strong><span>${label}</span></div></a>`).join('')}</div>`;}
function resources(){const d=state.data;return dashboardTiles()+tools()+cards()+NexoHealth.render(d)+`<div class="telemetry-charts"><section class="panel"><div class="panel-top"><div><h2>CPU y memoria</h2><p>Porcentaje de utilización</p></div><div class="chart-legend"><span class="cpu-dot">CPU</span><span class="ram-dot">RAM</span></div></div><div class="overlay-chart">${spark(state.history,'cpu','#b9f385',100,'%')}<div class="overlay">${spark(state.history,'memory','#8ec9fd',100,'%').replace(/<text[^>]*>.*?<\/text>/g,'').replace(/<line[^>]*\/>/g,'')}</div></div></section><section class="panel"><div class="panel-top"><div><h2>Tráfico de red</h2><p>Entrada y salida · escala compartida en bps</p></div><div class="chart-legend"><span class="tx-dot">Salida</span><span class="ram-dot">Entrada</span></div></div><div class="overlay-chart">${networkChart()}</div></section></div><div class="telemetry-bottom"><section class="panel"><div class="panel-top"><div><h2>Servidor y conexiones</h2><p>Métricas del sistema operativo</p></div><a class="link-button" href="#conexiones">Abrir mapa →</a></div><div class="server-details"><div><span>TCP establecidos</span><strong>${fmt(d?.connections.established,0)}</strong><small>En puertos ${esc(d?.connections.ports?.join(', ')||'configurados')}</small></div><div><span>Sesiones IPTV</span><strong>${d?.sessions!==null&&d?.sessions?fmt(d.sessions.length,0):'—'}</strong><small>${d?.sessions_status==='available'?'Reportadas por el servicio IPTV':'Integración de sesiones pendiente'}</small></div><div><span>Tiempo encendido</span><strong>${duration(d?.server.uptime_seconds)}</strong><small>${esc(d?.server.kernel||'Kernel no recibido')}</small></div><div><span>Interfaces medidas</span><strong>${d?esc(d.network.interfaces.map(i=>i.name).join(', ')||'—'):'—'}</strong><small>Las tasas no incluyen otras interfaces</small></div></div>${d?.disks.length>1?`<div class="extra-disks">${d.disks.map(v=>`<span>${esc(v.path)}: ${fmt(v.used_percent)}% · ${bytes(v.used_bytes)}</span>`).join('')}</div>`:''}</section>${alarmPanel()}</div>`+stamp()+(!d?`<section class="connect-callout"><div><strong>La infraestructura real empieza con un agente.</strong><p>Instala Nexo Monitor en tu Linux y conecta su dirección HTTPS. También puedes explorar el panel con datos de demostración.</p></div><a href="downloads/nexo-monitor.zip" download class="download-agent">↓ Descargar agente Linux</a></section>`:'');}
function networkChart(){const max=Math.max(1,...state.history.flatMap(p=>[p.tx,p.rx]).filter(Number.isFinite))*1.15;return spark(state.history,'tx','#f5c47a',max).replace(/<text x="0"[^>]*>.*?<\/text>/g,'')+`<div class="overlay">${spark(state.history,'rx','#8ec9fd',max).replace(/<text[^>]*>.*?<\/text>/g,'').replace(/<line[^>]*\/>/g,'')}</div><span class="chart-scale">${state.history.length?'Máximo de escala: '+rate(max):'Sin escala hasta recibir muestras'}</span>`;}
function peers(){const d=state.data;if(!d)return [];return d.connections.peers.map(p=>({...p,sessions:d.sessions?.filter(s=>s.ip===p.ip)||[]}));}
function topology(){const p=peers().slice(0,10);if(!p.length)return '<div class="map-empty"><span>◎</span><h3>Sin conexiones para dibujar</h3><p>El mapa aparecerá cuando el agente reporte sockets TCP en los puertos configurados.</p></div>';const positions=p.map((v,i)=>{const angle=(i/p.length)*Math.PI*2-Math.PI/2;return {x:500+365*Math.cos(angle),y:210+145*Math.sin(angle),...v};});return `<svg class="topology-svg" viewBox="0 0 1000 420" role="group" aria-label="Topología de conexiones TCP"><defs><radialGradient id="serverGlow"><stop stop-color="#8cba6a" stop-opacity=".18"/><stop offset="1" stop-color="#8cba6a" stop-opacity="0"/></radialGradient></defs><circle cx="500" cy="210" r="125" fill="url(#serverGlow)"/>${positions.map(v=>`<path d="M500 210 Q${(500+v.x)/2} ${v.y} ${v.x} ${v.y}" fill="none" stroke="${state.selected===v.ip?'#b9f385':'#355449'}" stroke-width="${Math.min(4,1+v.count/10)}" stroke-dasharray="5 5"/>`).join('')}<rect x="425" y="175" width="150" height="70" rx="12" fill="#213528" stroke="#8bb26a"/><text x="500" y="202" text-anchor="middle" fill="#c7f0ac" font-size="13">▤ SERVIDOR</text><text x="500" y="224" text-anchor="middle" fill="#a1b5a4" font-size="10">${esc(state.data.server.name.slice(0,22))}</text>${positions.map(v=>`<g class="peer-node" role="button" tabindex="0" aria-label="Ver conexión ${safeIP(v.ip)}" data-peer="${esc(v.ip)}"><circle cx="${v.x}" cy="${v.y}" r="18" fill="#182e35" stroke="${state.selected===v.ip?'#b9f385':'#68b2c3'}" stroke-width="1.5"/><text x="${v.x}" y="${v.y+4}" text-anchor="middle" fill="#bedde4" font-size="12">${v.count}</text><text x="${v.x}" y="${v.y+36}" text-anchor="middle" fill="#a5bac3" font-size="11">${safeIP(v.ip)}</text></g>`).join('')}</svg><div class="map-caption">${p.length} de ${state.data.connections.peers.length} IP reportadas · grosor de línea según sockets TCP · clic en un nodo para inspeccionar</div>`;}
function geography(){const d=state.data;const sessions=d?.sessions?.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon))||[];if(!sessions.length)return '<div class="map-empty"><span>⌖</span><h3>Sin ubicaciones reportadas</h3><p>La integración IPTV debe proporcionar latitud y longitud. No se deducen ubicaciones ni se envían IP a servicios externos.</p></div>';const points=sessions.slice(0,500);return `<div class="geo-map"><svg viewBox="0 0 1000 450" role="img" aria-label="Mapa geográfico de sesiones IPTV"><image href="world.svg" width="1000" height="450"/>${[-60,-30,0,30,60].map(lat=>`<line x1="0" x2="1000" y1="${C.project(lat,0)[1]}" y2="${C.project(lat,0)[1]}" stroke="#24363d" stroke-dasharray="2 6"/>`).join('')}${[-120,-60,0,60,120].map(lon=>`<line x1="${C.project(0,lon)[0]}" x2="${C.project(0,lon)[0]}" y1="0" y2="450" stroke="#24363d" stroke-dasharray="2 6"/>`).join('')}${points.map(s=>{const [x,y]=C.project(s.lat,s.lon);return `<circle cx="${x}" cy="${y}" r="5" fill="#b9f385" fill-opacity=".8" stroke="#15251b"><title>${esc(s.location||'Ubicación reportada')} · ${safeIP(s.ip)}</title></circle>`;}).join('')}</svg></div><div class="map-caption">${points.length} de ${d?.sessions?.length||0} sesiones con ubicación visibles · coordenadas aportadas por la integración</div>`;}
function connections(){const d=state.data,list=peers().filter(p=>[p.ip,...p.sessions.map(s=>s.client+' '+s.channel)].join(' ').toLowerCase().includes(state.filter.toLowerCase()));return tools()+`<div class="connection-totals"><div><span class="dot"></span><strong>${fmt(d?.connections.established,0)}</strong> sockets TCP establecidos</div><div><strong>${d?fmt(d.connections.peers.length,0):'—'}</strong> IP reportadas</div><div><strong>${d?.sessions?fmt(d.sessions.length,0):'—'}</strong> sesiones IPTV</div><span class="connection-warning">TCP ≠ espectadores</span></div><div class="map-layout"><section class="panel map-panel"><div class="panel-top"><div><h2>Mapa de conexiones</h2><p>${state.map==='topology'?'Servidor → conexiones entrantes por IP':'Distribución geográfica de las sesiones IPTV'}</p></div><div class="segmented"><button data-monitor="topology" aria-pressed="${state.map==='topology'}">Topología</button><button data-monitor="geography" aria-pressed="${state.map==='geography'}">Geografía</button></div></div>${state.map==='topology'?topology():geography()}</section><section class="panel inspect-panel"><div class="panel-top"><div><h2>Inspeccionar conexión</h2><p>Selecciona un nodo o una fila</p></div></div><div id="peer-inspect">${inspect()}</div></section></div><section class="panel connections-table"><div class="panel-top"><div><h2>Conexiones por IP</h2><p>${d?.sessions_status==='available'?'Sesiones reportadas por la integración IPTV':'Usuario, canal y bitrate requieren integración con el servicio IPTV.'}</p></div><div class="toolbar"><input id="connection-search" type="search" aria-label="Buscar conexión" placeholder="Buscar IP, cliente o canal…" value="${esc(state.filter)}"><button class="small" data-monitor="ips">${state.showIPs?'Ocultar IP':'Mostrar IP'}</button></div></div><div id="connection-results">${connectionRows(list)}</div></section>`+stamp();}
function connectionRows(list){if(!list.length)return '<div class="empty"><h3>Sin conexiones que mostrar</h3><p>Revisa el agente, los puertos configurados o el filtro de búsqueda.</p></div>';return `<div class="table-wrap"><table><thead><tr>${['IP REMOTA','SOCKETS TCP','SESIONES IPTV','CANALES','BITRATE IPTV','DETALLE'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${list.slice(0,200).map(p=>`<tr class="${p.ip===state.selected?'selected-row':''}"><td>${safeIP(p.ip)}</td><td>${fmt(p.count,0)}</td><td>${state.data.sessions?fmt(p.sessions.length,0):'—'}</td><td>${esc([...new Set(p.sessions.map(s=>s.channel).filter(Boolean))].join(', ')||'—')}</td><td>${p.sessions.length&&p.sessions.every(s=>s.bitrate_bps!==null)?rate(p.sessions.reduce((n,s)=>n+s.bitrate_bps,0)):'—'}</td><td><button class="small" data-peer="${esc(p.ip)}">Inspeccionar</button></td></tr>`).join('')}</tbody></table></div>${list.length>200?'<p class="table-limit">Se muestran 200 filas. Filtra para encontrar una IP.</p>':''}`;}
function inspect(){const p=peers().find(p=>p.ip===state.selected);return p?`<div class="peer-details"><span class="badge">TCP establecido</span><h3>${safeIP(p.ip)}</h3><dl><dt>Sockets TCP</dt><dd>${p.count}</dd><dt>Puertos observados</dt><dd>${esc(state.data.connections.ports.join(', '))}</dd><dt>Sesiones IPTV</dt><dd>${state.data.sessions?p.sessions.length:'No integradas'}</dd></dl>${p.sessions.map(s=>`<div class="session-detail"><strong>${esc(s.client||'Cliente sin nombre')}</strong><p>${esc(s.channel||'Canal sin informar')}</p><small>${s.started_at?'Duración: '+duration((Date.now()-Date.parse(s.started_at))/1000):'Duración no reportada'} · ${rate(s.bitrate_bps)}</small><p>${esc(s.location||'Sin ubicación')}</p></div>`).join('')}<p class="help">Los sockets son conexiones TCP, no una medida directa de espectadores. No incluye UDP ni QUIC.</p></div>`:'<div class="inspect-empty"><span>⌖</span><p>Aquí verás la IP, los sockets y las sesiones asociadas cuando estén integradas.</p></div>';}
function draw(){NexoShell.sync(state.data,state.mode,status()[0]);const focus=document.activeElement;const caret=focus?.id==='connection-search'?{start:focus.selectionStart,end:focus.selectionEnd}:null;const p=currentPage();if(p==='recursos'||p==='conexiones'){$('#view').innerHTML=p==='recursos'?resources():connections();const input=$('#connection-search');if(input)input.oninput=e=>{state.filter=e.target.value;$('#connection-results').innerHTML=connectionRows(peers().filter(p=>[p.ip,...p.sessions.map(s=>s.client+' '+s.channel)].join(' ').toLowerCase().includes(state.filter.toLowerCase())));};if(caret&&input){input.focus({preventScroll:true});input.setSelectionRange(caret.start,caret.end);}}else if(window.NexoServers?.isPage(p)){NexoServers.render();}else if(p==='inicio'){const panel=$('#monitor-summary');if(panel)panel.outerHTML=summary();}}
function receive(d){state.data=C.snapshot(d);if(state.mode==='live'&&!state.testProxy&&window.NexoServers)NexoServers.record(state.url,state.data,state.token,state.latency);state.received=Date.now();state.error='';const time=Date.parse(d.timestamp);const previous=state.history.at(-1);if(previous&&time-previous.time>10000)state.history.push({time:previous.time+1,cpu:null,memory:null,tx:null,rx:null});if(state.history.at(-1)?.time!==time)state.history.push({time,cpu:d.cpu.percent,memory:d.memory?.used_percent??null,tx:d.network.tx_bps,rx:d.network.rx_bps});state.history=state.history.filter(p=>time-p.time<=600000).slice(-120);draw();}
async function tick(){if(state.paused||state.busy||state.mode==='idle')return;if(state.mode==='demo'){receive(window.NexoServers?.demoSnapshot(state.demoServer)||C.demo());return;}state.busy=true;const rev=revision;controller=new AbortController();const abort=setTimeout(()=>controller?.abort(),4000);try{state.lastAttempt=Date.now();const started=performance.now();const r=await fetch(state.url+'/v1/snapshot',{headers:state.testProxy?{}:{Authorization:'Bearer '+state.token},cache:'no-store',credentials:state.testProxy?'same-origin':'omit',redirect:'error',referrerPolicy:'no-referrer',signal:controller.signal});if(rev!==revision)return;if(!r.ok)throw Error(r.status===401?'Token rechazado por el agente.':r.status===403?'Origen del panel no autorizado por el agente.':'El agente respondió HTTP '+r.status+'.');if(Number(r.headers.get('Content-Length'))>3e6)throw Error('Respuesta demasiado grande.');const text=await r.text();if(text.length>3e6)throw Error('Respuesta demasiado grande.');if(rev===revision){state.latency=performance.now()-started;receive(JSON.parse(text));}}catch(e){if(rev===revision){state.error=e.name==='AbortError'?'El agente no respondió en 4 segundos.':e instanceof TypeError?'No se pudo acceder. Revisa HTTPS, CORS, DNS y el servicio del agente.':e.message;window.NexoServers?.failURL(state.url,state.error);draw();}}finally{clearTimeout(abort);state.busy=false;}}
function restart(mode){revision++;controller?.abort();clearInterval(timer);state.mode=mode;state.paused=false;state.error='';state.data=null;state.history=[];state.selected=null;state.latency=null;draw();tick();timer=setInterval(tick,5000);}
function settings(){const dialog=$('#monitor-settings');$('#agent-url').value=state.url;$('#agent-token').value='';$('#monitor-config-error').textContent='';dialog.showModal();}
function summary(){const [st,label]=status();return `<section id="monitor-summary" class="monitor-summary panel"><div><span class="live-status ${st}"><i></i>${label}</span><h2>Recursos y conexiones del servidor</h2><p>${state.data?'CPU '+fmt(state.data.cpu.percent)+'% · RAM '+fmt(state.data.memory?.used_percent)+'% · Salida '+rate(state.data.network.tx_bps):'Conecta tu Linux para recibir CPU, RAM, disco, red y conexiones cada 5 segundos.'}</p></div><a class="primary" href="#recursos">Abrir centro de operación →</a></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-monitor],[data-peer]');if(!b)return;if(b.dataset.peer){state.selected=b.dataset.peer;draw();return;}switch(b.dataset.monitor){case 'settings':settings();break;case 'demo':state.testProxy=false;state.demoServer=null;state.token='';restart(state.mode==='demo'?'idle':'demo');break;case 'pause':state.paused=!state.paused;draw();if(!state.paused)tick();break;case 'topology':state.map='topology';draw();break;case 'geography':state.map='geography';draw();break;case 'ips':state.showIPs=!state.showIPs;draw();break;case 'disconnect':window.NexoServers?.disconnectURL(state.url);state.token='';restart('idle');$('#monitor-settings').close();break;case 'close':$('#monitor-settings').close();break;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-peer]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('DOMContentLoaded',()=>{if(document.querySelector('meta[name="nexo-test"]')?.content==='loopback'&&location.protocol==='http:'&&location.hostname==='localhost'){state.testProxy=true;state.url=location.origin;state.token='';restart('live');}$('#monitor-form').onsubmit=e=>{e.preventDefault();try{const u=new URL($('#agent-url').value.trim());if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||(u.pathname!=='/'&&u.pathname!==''))throw Error('Usa el origen HTTPS del agente, sin ruta, credenciales ni parámetros.');const token=$('#agent-token').value.trim();if(token.length<32||token.length>4096||!/^[\x21-\x7E]+$/.test(token))throw Error('Introduce el token ASCII de al menos 32 caracteres del agente.');state.testProxy=false;state.url=u.origin;state.token=token;try{localStorage.setItem('nexo-monitor-url',state.url);}catch{}$('#monitor-settings').close();restart('live');}catch(err){$('#monitor-config-error').textContent=err.message;}};$('#monitor-settings').addEventListener('close',()=>{$('#agent-token').value='';});});
return {isPage:p=>['recursos','conexiones'].includes(p),draw,summary,settings,current:()=>({mode:state.mode,url:state.url,paused:state.paused}),useServer:(url,token)=>{state.testProxy=false;state.url=url;state.token=token;state.demoServer=null;restart('live');},disconnect:()=>{state.testProxy=false;window.NexoServers?.disconnectURL(state.url);state.token='';restart('idle');},showDemoServer:id=>{state.demoServer=id;restart('demo');}};
})();
